`lab08.py` শুরু করো। ডেটাবেসের বদলে একটা dict ব্যবহার করছি।

```python
import os, json
import anthropic

client = anthropic.Anthropic()
MODEL = os.environ["CLAUDE_MODEL"]

ORDERS = {
    "CC-1042": {"status": "out_for_delivery", "eta": "today 6pm", "total": 450, "refund_issued": False},
    "CC-1043": {"status": "delivered", "eta": None, "total": 780, "refund_issued": False},
}

TOOLS = [
    {
        "name": "get_order_status",
        "description": (
            "Looks up the current status of ONE ChaiCart order by its order number "
            "(format CC- followed by digits, e.g. CC-1042). Returns status "
            "(placed, packed, out_for_delivery, delivered, cancelled), delivery estimate, "
            "total in BDT and whether a refund was already issued. Use it whenever the customer "
            "asks where their order is. Do NOT use it to search by phone or name. "
            "It is read-only and cannot change the order."
        ),
        "input_schema": {
            "type": "object",
            "properties": {
                "order_id": {"type": "string", "description": "Order number as on the receipt, e.g. CC-1042."}
            },
            "required": ["order_id"],
        },
    },
    {
        "name": "issue_refund",
        "description": (
            "Refunds the full amount of ONE delivered order. IRREVERSIBLE: money is sent back. "
            "Use only after the customer clearly asked for a refund AND the order status is delivered "
            "(check with get_order_status first). Do not use for orders still in transit. "
            "Returns a refund id. A human must approve each refund; if approval is denied "
            "the tool returns an error and you must tell the customer a staff member will follow up."
        ),
        "input_schema": {
            "type": "object",
            "properties": {
                "order_id": {"type": "string", "description": "Order number, e.g. CC-1043."},
                "reason": {"type": "string", "enum": ["damaged", "late", "wrong_item", "other"],
                           "description": "Why the customer wants the refund."},
            },
            "required": ["order_id", "reason"],
        },
    },
]
```

**প্রত্যাশিত পর্যবেক্ষণ:** এখনও কিছু চালানো হয়নি। শুধু ফাইল সেভ করো। দেখো: কোন কোন জায়গায় description-এ "কখন ব্যবহার করবে না" লেখা আছে?

Tool-এর আসল code আর `run_tool` dispatcher যোগ করো। এখানে timeout-এর একটা কৃত্রিম অবস্থা আছে (`CC-5000`)।

```python
def get_order_status(order_id: str):
    if order_id == "CC-5000":
        raise TimeoutError("order service did not answer")
    order = ORDERS.get(order_id)
    if order is None:
        return "Order not found. Order numbers look like CC-1042. Ask the customer to re-check the receipt.", True
    return json.dumps(order, ensure_ascii=False), False

def issue_refund(order_id: str, reason: str, confirm):
    order = ORDERS.get(order_id)
    if order is None:
        return "Order not found. Do not retry with the same id.", True
    if order["status"] != "delivered":
        return f"Refund blocked: order is {order['status']}. Refunds are allowed only for delivered orders.", True
    if order["refund_issued"]:
        return "Refund already issued for this order.", True
    if not confirm(f"{order_id}-এ {order['total']} টাকা refund ({reason}) করবেন?"):
        return "Refund NOT executed: staff did not approve. Tell the customer a staff member will follow up.", True
    order["refund_issued"] = True
    return json.dumps({"refund_id": "RF-1", "amount": order["total"]}), False

def run_tool(name: str, args: dict, confirm):
    """Harness dispatch: lookup, validate, execute, package. Returns (content, is_error)."""
    try:
        if name == "get_order_status":
            return get_order_status(args["order_id"])
        if name == "issue_refund":
            return issue_refund(args["order_id"], args["reason"], confirm)
        return f"Unknown tool '{name}'. Available: get_order_status, issue_refund.", True
    except TimeoutError:
        return "Order service timed out. This is usually temporary: retry once; if it fails again tell the customer we cannot check right now.", True
    except KeyError as e:
        return f"Missing required parameter {e}. Provide it and try again.", True
    except Exception:
        return "Internal tool error. Do not retry; apologise and offer a staff callback.", True   # stack trace/secret কখনও নয়
```

**প্রত্যাশিত পর্যবেক্ষণ:** `run_tool` কখনও exception বাইরে ছুঁড়ে না। প্রতিটা ফল `(content, is_error)` জোড়া। কেন stack trace ফেরত দিইনি, ভাবো।
